// Generates testdata/transform-kat.txt: the answers the JDK's javax.xml.xpath gives for every
// XML-DSig transform expression in the upstream dss-xades corpus, evaluated exactly the way
// Apache Santuario 3.0.6 evaluates it.
//
// Santuario 3.0 dropped Xalan; org.apache.xml.security.utils.JDKXPathAPI compiles the
// expression with javax.xml.xpath.XPathFactory under a DOMNamespaceContext built from the
// element that CARRIES the expression, and then either
//
//   - evaluates XPathConstants.BOOLEAN once per candidate node (the ds:XPath transform's
//     XPathNodeFilter), or
//   - evaluates XPathConstants.NODESET once against the owner document (the XPath Filter 2.0
//     transform, whose result is a set of subtree roots).
//
// Both are emitted for every expression, because internal/xpath10 must answer both.
//
// Nodes are named by a structural key, not by an index, so that the two sides agree without
// agreeing on an attribute order: Xerces' NamedNodeMap sorts attributes by node name while
// internal/xmldom keeps them in document order, and an index-based encoding would compare
// those orders instead of the XPath answers. The key of an element is the path of child
// indices from the document node ("/0/2/1"); an attribute appends "@" and its QName; a text,
// CDATA, comment or processing-instruction node is just its own child index.
//
// Run with OpenJDK 21; gen/generate-transform.sh does it.
import org.w3c.dom.Attr;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NamedNodeMap;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import javax.xml.XMLConstants;
import javax.xml.namespace.NamespaceContext;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpression;
import javax.xml.xpath.XPathFactory;

import java.io.File;
import java.io.FileInputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public final class TransformXPathOracle {

    private static final String DS = "http://www.w3.org/2000/09/xmldsig#";
    private static final String F2 = "http://www.w3.org/2002/06/xmldsig-filter2";

    private static final StringBuilder OUT = new StringBuilder();

    public static void main(String[] args) throws Exception {
        Path corpusDir = Paths.get(args[0]);
        Path katFile = Paths.get(args[1]);

        OUT.append("# Known answers for the XML-DSig transform expressions of internal/xpath10.\n");
        OUT.append("# Generated by gen/TransformXPathOracle.java against the JDK 21 XPath, which is\n");
        OUT.append("# the engine Apache Santuario 3.0.6 uses (JDKXPathAPI). Do not edit by hand.\n");
        OUT.append("#\n");
        OUT.append("# fixture\txpathIndex\tmode\texpression\tanswer\n");
        OUT.append("# mode 'bool' lists the keys of the nodes whose boolean evaluation is true;\n");
        OUT.append("# mode 'nodeset' lists the keys the node-set evaluation selects, in its own order.\n");
        OUT.append("# An answer of '!<ExceptionClass>' means the JDK refused the expression.\n");

        List<Path> files = new ArrayList<>();
        try (var walk = Files.walk(corpusDir)) {
            walk.filter(p -> p.toString().endsWith(".xml")).sorted().forEach(files::add);
        }
        for (Path p : files) {
            String rel = corpusDir.relativize(p).toString().replace(File.separatorChar, '/');
            try {
                run(rel, p.toFile());
            } catch (Throwable t) {
                OUT.append(String.join("\t", rel, "-", "fixture", "-", "!" + t.getClass().getSimpleName()))
                   .append('\n');
            }
        }
        Files.write(katFile, OUT.toString().getBytes(StandardCharsets.UTF_8));
        System.out.println("wrote " + katFile);
    }

    private static void run(String fixture, File file) throws Exception {
        Document doc = parse(file);
        // XAdESDOMDocument.recursiveIdBrowse, without which getElementById - and therefore the
        // id() function - answers null for every reference in the corpus.
        registerIds(doc.getDocumentElement());
        List<Element> xpathElements = new ArrayList<>();
        collect(doc.getDocumentElement(), xpathElements);
        if (xpathElements.isEmpty()) {
            return;
        }
        List<Node> all = new ArrayList<>();
        collectNodes(doc, all);

        for (int i = 0; i < xpathElements.size(); i++) {
            Element xp = xpathElements.get(i);
            String expr = textOf(xp);
            emitBoolean(fixture, i, expr, xp, all);
            emitNodeSet(fixture, i, expr, xp, doc);
        }
    }

    /** Every ds:XPath and xpf:XPath element, in document order. */
    private static void collect(Node n, List<Element> out) {
        if (n.getNodeType() == Node.ELEMENT_NODE && "XPath".equals(n.getLocalName())
                && (DS.equals(n.getNamespaceURI()) || F2.equals(n.getNamespaceURI()))) {
            out.add((Element) n);
        }
        for (Node c = n.getFirstChild(); c != null; c = c.getNextSibling()) {
            collect(c, out);
        }
    }

    /** XMLUtils.getStrFromNode over the element's first child: all text-node children joined. */
    private static String textOf(Element el) {
        StringBuilder sb = new StringBuilder();
        for (Node c = el.getFirstChild(); c != null; c = c.getNextSibling()) {
            if (c.getNodeType() == Node.TEXT_NODE || c.getNodeType() == Node.CDATA_SECTION_NODE) {
                sb.append(c.getNodeValue());
            }
        }
        return sb.toString();
    }

    private static void emitBoolean(String fixture, int i, String expr, Element xp, List<Node> all) {
        List<String> keys = new ArrayList<>();
        try {
            XPathExpression compiled = compile(expr, xp);
            for (Node n : all) {
                Boolean b = (Boolean) compiled.evaluate(n, XPathConstants.BOOLEAN);
                if (Boolean.TRUE.equals(b)) {
                    keys.add(key(n));
                }
            }
        } catch (Throwable t) {
            emit(fixture, i, "bool", expr, "!" + t.getClass().getSimpleName());
            return;
        }
        // The boolean answer is a SET, and the two sides enumerate an element's attributes in
        // different orders - Xerces sorts a NamedNodeMap by node name, internal/xmldom keeps
        // source order - so it is compared sorted.
        java.util.Collections.sort(keys);
        emit(fixture, i, "bool", expr, String.join(" ", keys));
    }

    private static void emitNodeSet(String fixture, int i, String expr, Element xp, Document doc) {
        StringBuilder keys = new StringBuilder();
        try {
            XPathExpression compiled = compile(expr, xp);
            NodeList nl = (NodeList) compiled.evaluate(doc, XPathConstants.NODESET);
            for (int j = 0; j < nl.getLength(); j++) {
                if (keys.length() > 0) {
                    keys.append(' ');
                }
                keys.append(key(nl.item(j)));
            }
        } catch (Throwable t) {
            emit(fixture, i, "nodeset", expr, "!" + t.getClass().getSimpleName());
            return;
        }
        emit(fixture, i, "nodeset", expr, keys.toString());
    }

    private static XPathExpression compile(String expr, Element namespaceNode) throws Exception {
        XPathFactory xpf = XPathFactory.newInstance();
        xpf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, Boolean.TRUE);
        XPath xpath = xpf.newXPath();
        xpath.setNamespaceContext(new ElementNamespaceContext(namespaceNode));
        return xpath.compile(expr);
    }

    /** DOMNamespaceContext: prefixes resolved against the declarations in scope on one element. */
    static final class ElementNamespaceContext implements NamespaceContext {
        private final Node node;

        ElementNamespaceContext(Node node) {
            this.node = node;
        }

        @Override
        public String getNamespaceURI(String prefix) {
            if (XMLConstants.XML_NS_PREFIX.equals(prefix)) {
                return XMLConstants.XML_NS_URI;
            }
            String uri = node.lookupNamespaceURI(prefix);
            return uri == null ? XMLConstants.NULL_NS_URI : uri;
        }

        @Override
        public String getPrefix(String namespaceURI) {
            return node.lookupPrefix(namespaceURI);
        }

        @Override
        public Iterator<String> getPrefixes(String namespaceURI) {
            String p = getPrefix(namespaceURI);
            return p == null ? List.<String>of().iterator() : List.of(p).iterator();
        }
    }

    /** Every node the canonicalizer can ask about: the document, elements, their attributes, and
     *  all character-data, comment and processing-instruction nodes. */
    private static void collectNodes(Node n, List<Node> out) {
        out.add(n);
        if (n.getNodeType() == Node.ELEMENT_NODE) {
            NamedNodeMap attrs = n.getAttributes();
            for (int i = 0; i < attrs.getLength(); i++) {
                out.add(attrs.item(i));
            }
        }
        for (Node c = n.getFirstChild(); c != null; c = c.getNextSibling()) {
            collectNodes(c, out);
        }
    }

    /** The structural key described in the header comment. */
    private static String key(Node n) {
        if (n.getNodeType() == Node.ATTRIBUTE_NODE) {
            Attr a = (Attr) n;
            return key(a.getOwnerElement()) + "@" + a.getName();
        }
        if (n.getNodeType() == Node.DOCUMENT_NODE) {
            return "/";
        }
        Node parent = n.getParentNode();
        int index = 0;
        for (Node c = parent.getFirstChild(); c != null; c = c.getNextSibling()) {
            if (c == n) {
                break;
            }
            index++;
        }
        return key(parent) + "/" + index;
    }

    /** XAdESDOMDocument.recursiveIdBrowse + setIDIdentifier, verbatim. */
    private static void registerIds(Element element) {
        NamedNodeMap attributes = element.getAttributes();
        for (int jj = 0; jj < attributes.getLength(); jj++) {
            Node item = attributes.item(jj);
            String localName = item.getLocalName();
            if (localName != null && "Id".equalsIgnoreCase(localName)) {
                element.setIdAttribute(item.getNodeName(), true);
                break;
            }
        }
        NodeList children = element.getChildNodes();
        for (int ii = 0; ii < children.getLength(); ii++) {
            if (children.item(ii).getNodeType() == Node.ELEMENT_NODE) {
                registerIds((Element) children.item(ii));
            }
        }
    }

    private static Document parse(File f) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        dbf.setNamespaceAware(true);
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbf.setXIncludeAware(false);
        try (InputStream in = new FileInputStream(f)) {
            return dbf.newDocumentBuilder().parse(in);
        }
    }

    private static void emit(String fixture, int i, String mode, String expr, String answer) {
        OUT.append(String.join("\t", fixture, String.valueOf(i), mode,
                expr.replace("\t", "    ").replace("\n", " "), answer)).append('\n');
    }

    private TransformXPathOracle() {
    }
}
